import { formatAddressLines } from './addresses.js';

/** Where customers follow their parcels. */
const TRACKING_PAGE_URL = 'https://shop.example.com/tracking';

/** Returns the text of the email that tells a customer their order has shipped. */
export function shippingConfirmationText(shipment) {
  return [
    `Your order ${shipment.orderId} is on its way.`,
    `Tracking number: ${shipment.trackingNumber}`,
    `Follow it at ${TRACKING_PAGE_URL}/${shipment.trackingNumber}`,
    '',
    'We are sending it to:',
    ...formatAddressLines(shipment.address),
  ].join('\n');
}
import { formatAddressLines } from './addresses.js';
import { callCarrier } from './carrier.js';

/** A parcel declared at more than this many cents needs a signature on delivery. */
export const SIGNATURE_THRESHOLD_CENTS = 100_000;

/** Asks the carrier for a shipment's label, and returns the shipment with its tracking number and label. */
export async function createLabel(shipment, transport) {
  const payload = {
    reference: shipment.orderId,
    addressLines: formatAddressLines(shipment.address),
    weightGrams: shipment.parcel.weightGrams,
    signatureRequired: shipment.declaredValueCents > SIGNATURE_THRESHOLD_CENTS,
  };
  try {
    const answer = await callCarrier(transport, 'label', payload);
    return { ...shipment, trackingNumber: answer.trackingNumber, label: answer.label };
  } catch (error) {
    throw new Error(`The carrier gave no label for order ${shipment.orderId}`, { cause: error });
  }
}

/** Creates the labels of several shipments, and returns the shipments in the same order. */
export function createLabels(shipments, transport) {
  return Promise.all(shipments.map((shipment) => createLabel(shipment, transport)));
}
/** Returns the lines of an address as they are printed: name, street, postcode and city, country. */
export function formatAddressLines(address) {
  const cityLine = `${normalizePostcode(address.postcode)} ${address.city}`;
  return [address.name, address.street.trim(), cityLine, address.country].map(toPrintable);
}

// Letters that do not split into a plain letter plus an accent, so they need their own replacement.
const STANDALONE_LETTERS = {
  ß: 'ss', ẞ: 'SS', æ: 'ae', Æ: 'AE', œ: 'oe', Œ: 'OE',
  ø: 'o', Ø: 'O', đ: 'd', Đ: 'D', ð: 'd', Ð: 'D', ł: 'l', Ł: 'L', þ: 'th', Þ: 'TH', ı: 'i',
};

/** Replaces accented letters with plain ASCII ones, because the label printers print "?" for anything else. */
function toPrintable(text) {
  return text
    .replace(/[ßẞæÆœŒøØđĐðÐłŁþÞı]/g, (letter) => STANDALONE_LETTERS[letter])
    .normalize('NFD')
    .replace(/\p{M}/gu, '');
}

/** Returns a postcode in capitals, with single spaces and none around it. */
export function normalizePostcode(postcode) {
  return postcode.trim().toUpperCase().replace(/\s+/g, ' ');
}
