import assert from 'node:assert/strict';
import test from 'node:test';
import { shippingConfirmationText } from '../lib/notifications.js';

const address = {
  name: 'Ada Byrne',
  street: '12 Harbour Road',
  postcode: 'D02 X285',
  city: 'Dublin',
  country: 'IE',
};
const shipment = { orderId: 'ord_1', trackingNumber: 'SH0000000042', address };

test('tells the customer the order, the tracking number and the address', () => {
  const text = shippingConfirmationText(shipment);
  for (const part of ['ord_1', 'SH0000000042', 'Ada Byrne', '12 Harbour Road', 'D02 X285 Dublin']) {
    assert.ok(text.includes(part), part);
  }
});

test('links to the tracking page of the parcel', () => {
  assert.ok(shippingConfirmationText(shipment).includes('https://shop.example.com/tracking/SH0000000042'));
});
# shipping-service

Buys carrier labels for the shop's orders and quotes their shipping costs. It has no dependencies: it runs on Node.js 22 or later alone.

`npm test` runs the tests in `test/`. The carrier is never called by a test: each one passes a fake transport.

| Path | Holds |
|---|---|
| `lib/labels.js` | Carrier labels for shipments |
| `lib/rates.js` | Shipping costs and the carrier's rate quotes |
| `lib/parcels.js` | Parcel weights |
| `lib/addresses.js` | Address lines |
| `lib/tracking.js` | Tracking numbers and shipment statuses |
| `lib/notifications.js` | Emails to customers |
| `lib/carrier.js` | Requests to the carrier API, through a transport that makes the HTTP call |
| `lib/retry.js` | Retries of carrier requests |
| `lib/config.js` | Settings read from environment variables |
{
  "name": "shipping-service",
  "version": "0.2.0",
  "private": true,
  "type": "module",
  "description": "Buys carrier labels for the shop's orders and quotes their shipping costs.",
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=22"
  }
}

