    formatAddressLines({ name: 'José Müller', street: 'Hauptstraße 5', postcode: '1010', city: 'Wién', country: 'AT' }),
    ['Jose Muller', 'Hauptstrasse 5', '1010 Wien', 'AT'],
  );
});

