  assert.equal(formatAddressLines({ ...address, city: 'København' })[2], 'D02 X285 Kobenhavn');
  assert.equal(formatAddressLines({ ...address, street: 'ul. Łąkowa 3' })[1], 'ul. Lakowa 3');
});

